insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-solar-eclipse-2026-trivia',
  'Total Solar Eclipse 2026 Trivia: The Sky Goes Dark',
  'Eight questions on the total solar eclipse of August 12, 2026: the path of totality, why it happens and how to watch it safely.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What happens during a total solar eclipse?","options":[{"id":"a","text":"The Moon covers the entire solar disk","is_correct":true},{"id":"b","text":"Earth''s shadow falls on the Moon","is_correct":false},{"id":"c","text":"The Sun disappears behind Mars","is_correct":false},{"id":"d","text":"Venus crosses in front of the Sun","is_correct":false}],"explanation":"A total solar eclipse happens when the Moon passes between the Sun and Earth and completely covers the solar disk."},{"id":"q2","question":"On what date will the 2026 total solar eclipse take place?","options":[{"id":"a","text":"August 12, 2026","is_correct":true},{"id":"b","text":"June 21, 2026","is_correct":false},{"id":"c","text":"August 2, 2027","is_correct":false},{"id":"d","text":"April 8, 2024","is_correct":false}],"explanation":"The eclipse falls on August 12, 2026; the August 2027 eclipse crosses North Africa and the April 2024 one crossed North America."},{"id":"q3","question":"Why can the Moon cover the whole Sun even though it is much smaller?","options":[{"id":"a","text":"It is about 400 times closer, so their apparent sizes match","is_correct":true},{"id":"b","text":"It speeds up exactly during eclipses","is_correct":false},{"id":"c","text":"The Sun shrinks around noon","is_correct":false},{"id":"d","text":"Earth''s atmosphere magnifies the Moon","is_correct":false}],"explanation":"The Sun is about 400 times wider than the Moon, but also about 400 times farther away, so both look the same size in the sky."},{"id":"q4","question":"What is the name of the darkest part of the Moon''s shadow, where totality is visible?","options":[{"id":"a","text":"The umbra","is_correct":true},{"id":"b","text":"The penumbra","is_correct":false},{"id":"c","text":"The antumbra","is_correct":false},{"id":"d","text":"The terminator","is_correct":false}],"explanation":"Inside the umbra the Sun is fully blocked; observers in the penumbra only see a partial eclipse."},{"id":"q5","question":"Which part of the Sun becomes visible to the naked eye only during totality?","options":[{"id":"a","text":"The corona","is_correct":true},{"id":"b","text":"The photosphere","is_correct":false},{"id":"c","text":"Sunspots","is_correct":false},{"id":"d","text":"The solar core","is_correct":false}],"explanation":"The corona, the Sun''s faint outer atmosphere, is normally outshone by the disk and appears only while the disk is blocked."},{"id":"q6","question":"Which of these countries lies inside the path of totality on August 12, 2026?","options":[{"id":"a","text":"Spain","is_correct":true},{"id":"b","text":"Portugal","is_correct":false},{"id":"c","text":"Italy","is_correct":false},{"id":"d","text":"Germany","is_correct":false}],"explanation":"The path of totality crosses Greenland, Iceland and Spain; the rest of Europe sees only a partial eclipse."},{"id":"q7","question":"About how long does totality last at most during this eclipse?","options":[{"id":"a","text":"About 2 minutes and 18 seconds","is_correct":true},{"id":"b","text":"About 30 seconds","is_correct":false},{"id":"c","text":"About 7 minutes and 30 seconds","is_correct":false},{"id":"d","text":"More than one hour","is_correct":false}],"explanation":"Maximum totality happens near Iceland, about 2 minutes 18 seconds; in Spain it lasts roughly a minute and a half."},{"id":"q8","question":"When is it safe to look at the eclipse without certified solar filters?","options":[{"id":"a","text":"Only during the brief minutes of totality","is_correct":true},{"id":"b","text":"Any time, as long as you blink often","is_correct":false},{"id":"c","text":"Whenever the Sun looks dim","is_correct":false},{"id":"d","text":"Never under any circumstances","is_correct":false}],"explanation":"You can look without protection only while the Sun is completely covered; every partial phase requires certified eclipse glasses."}]'::jsonb,
  null,
  array['solar eclipse', 'astronomy', 'totality', '2026']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-eclipse-solar-2026',
  'Trivia del eclipse solar total del 12 de agosto de 2026',
  'Ocho preguntas sobre el eclipse solar total del 12 de agosto de 2026: la franja de totalidad, por qué ocurre y cómo observarlo sin riesgo.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Qué ocurre durante un eclipse solar total?","options":[{"id":"a","text":"La Luna cubre por completo el disco del Sol","is_correct":true},{"id":"b","text":"La sombra de la Tierra cae sobre la Luna","is_correct":false},{"id":"c","text":"El Sol desaparece detrás de Marte","is_correct":false},{"id":"d","text":"Venus cruza frente al Sol","is_correct":false}],"explanation":"Un eclipse solar total sucede cuando la Luna pasa entre el Sol y la Tierra y cubre por completo el disco solar."},{"id":"q2","question":"¿En qué fecha ocurrirá el eclipse solar total de 2026?","options":[{"id":"a","text":"El 12 de agosto de 2026","is_correct":true},{"id":"b","text":"El 21 de junio de 2026","is_correct":false},{"id":"c","text":"El 2 de agosto de 2027","is_correct":false},{"id":"d","text":"El 8 de abril de 2024","is_correct":false}],"explanation":"El eclipse será el 12 de agosto de 2026; el de agosto de 2027 cruzará el norte de África y el de abril de 2024 cruzó Norteamérica."},{"id":"q3","question":"¿Por qué la Luna puede cubrir todo el Sol si es mucho más pequeña?","options":[{"id":"a","text":"Está unas 400 veces más cerca, así que sus tamaños aparentes coinciden","is_correct":true},{"id":"b","text":"Acelera justo durante los eclipses","is_correct":false},{"id":"c","text":"El Sol se encoge al mediodía","is_correct":false},{"id":"d","text":"La atmósfera terrestre agranda la Luna","is_correct":false}],"explanation":"El Sol es unas 400 veces más ancho que la Luna, pero también está unas 400 veces más lejos, por eso se ven del mismo tamaño."},{"id":"q4","question":"¿Cómo se llama la parte más oscura de la sombra lunar, donde se ve la totalidad?","options":[{"id":"a","text":"La umbra","is_correct":true},{"id":"b","text":"La penumbra","is_correct":false},{"id":"c","text":"La antumbra","is_correct":false},{"id":"d","text":"El terminador","is_correct":false}],"explanation":"Dentro de la umbra el Sol queda totalmente bloqueado; quienes están en la penumbra solo ven un eclipse parcial."},{"id":"q5","question":"¿Qué parte del Sol se hace visible a simple vista solo durante la totalidad?","options":[{"id":"a","text":"La corona","is_correct":true},{"id":"b","text":"La fotosfera","is_correct":false},{"id":"c","text":"Las manchas solares","is_correct":false},{"id":"d","text":"El núcleo solar","is_correct":false}],"explanation":"La corona, la tenue atmósfera exterior del Sol, queda eclipsada por el brillo del disco y solo aparece cuando este se bloquea."},{"id":"q6","question":"¿Cuál de estos países queda dentro de la franja de totalidad el 12 de agosto de 2026?","options":[{"id":"a","text":"España","is_correct":true},{"id":"b","text":"Portugal","is_correct":false},{"id":"c","text":"Italia","is_correct":false},{"id":"d","text":"Alemania","is_correct":false}],"explanation":"La franja de totalidad cruza Groenlandia, Islandia y España; el resto de Europa solo verá un eclipse parcial."},{"id":"q7","question":"¿Cuánto dura como máximo la totalidad en este eclipse?","options":[{"id":"a","text":"Unos 2 minutos y 18 segundos","is_correct":true},{"id":"b","text":"Unos 30 segundos","is_correct":false},{"id":"c","text":"Unos 7 minutos y 30 segundos","is_correct":false},{"id":"d","text":"Más de una hora","is_correct":false}],"explanation":"La totalidad máxima se da cerca de Islandia, unos 2 minutos 18 segundos; en España dura aproximadamente un minuto y medio."},{"id":"q8","question":"¿Cuándo es seguro mirar el eclipse sin filtros solares certificados?","options":[{"id":"a","text":"Solo durante los breves minutos de totalidad","is_correct":true},{"id":"b","text":"En cualquier momento, con tal de parpadear seguido","is_correct":false},{"id":"c","text":"Siempre que el Sol se vea tenue","is_correct":false},{"id":"d","text":"Nunca, bajo ninguna circunstancia","is_correct":false}],"explanation":"Solo mientras el Sol está completamente cubierto se puede mirar sin protección; cada fase parcial exige gafas certificadas."}]'::jsonb,
  null,
  array['eclipse solar', 'astronomía', 'totalidad', '2026']::text[],
  3,
  'published',
  false,
  false,
  now()
)
