insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-generative-ai-trivia',
  'Generative AI Trivia: How Language Models Work',
  'Eight questions on generative AI: tokens, transformers, training, hallucinations and why these systems have limits.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"What does a generative AI system produce?","options":[{"id":"a","text":"New content such as text, images or audio","is_correct":true},{"id":"b","text":"Only classifications of existing data","is_correct":false},{"id":"c","text":"Physical objects on demand","is_correct":false},{"id":"d","text":"Verified mathematical proofs","is_correct":false}],"explanation":"Generative models create new content that resembles their training data, unlike systems that only classify or predict."},{"id":"q2","question":"In a language model, what is a token?","options":[{"id":"a","text":"A small chunk of text, such as a word or a word piece","is_correct":true},{"id":"b","text":"A paid subscription level","is_correct":false},{"id":"c","text":"A unit of computing power","is_correct":false},{"id":"d","text":"A saved conversation","is_correct":false}],"explanation":"Models split text into tokens — whole words, word fragments or characters — and process those pieces."},{"id":"q3","question":"Which architecture, introduced in a 2017 paper, powers modern language models?","options":[{"id":"a","text":"The transformer","is_correct":true},{"id":"b","text":"The perceptron","is_correct":false},{"id":"c","text":"The decision tree","is_correct":false},{"id":"d","text":"The convolutional network","is_correct":false}],"explanation":"The paper ''Attention Is All You Need'' introduced the transformer, whose attention mechanism is the base of today''s LLMs."},{"id":"q4","question":"During pretraining, what does a language model learn to do?","options":[{"id":"a","text":"Predict the next token in a text","is_correct":true},{"id":"b","text":"Look up answers in a database","is_correct":false},{"id":"c","text":"Follow a fixed script","is_correct":false},{"id":"d","text":"Copy web pages word by word","is_correct":false}],"explanation":"Pretraining adjusts billions of weights so the model gets better at predicting which token comes next."},{"id":"q5","question":"What is an AI ''hallucination''?","options":[{"id":"a","text":"A confident answer that is actually false or made up","is_correct":true},{"id":"b","text":"A model refusing to answer","is_correct":false},{"id":"c","text":"A visual bug in the interface","is_correct":false},{"id":"d","text":"A type of cyberattack","is_correct":false}],"explanation":"Hallucinations happen because models generate plausible-sounding text without a built-in truth check."},{"id":"q6","question":"What is fine-tuning?","options":[{"id":"a","text":"Extra training of a base model on specific data or tasks","is_correct":true},{"id":"b","text":"Deleting half the model to speed it up","is_correct":false},{"id":"c","text":"Rewriting the model''s source code","is_correct":false},{"id":"d","text":"Connecting the model to the internet","is_correct":false}],"explanation":"Fine-tuning takes a pretrained model and keeps training it on narrower data to specialize its behavior."},{"id":"q7","question":"What does RLHF add to a model''s training?","options":[{"id":"a","text":"Human feedback that guides answers toward helpful behavior","is_correct":true},{"id":"b","text":"More graphics cards in the data center","is_correct":false},{"id":"c","text":"A second model that translates every output","is_correct":false},{"id":"d","text":"Hard-coded grammar rules","is_correct":false}],"explanation":"Reinforcement learning from human feedback uses people''s ratings of answers to refine the model''s behavior."},{"id":"q8","question":"What is a model''s context window?","options":[{"id":"a","text":"The maximum amount of text it can consider at once","is_correct":true},{"id":"b","text":"The time limit for each answer","is_correct":false},{"id":"c","text":"The screen where results appear","is_correct":false},{"id":"d","text":"The number of languages it knows","is_correct":false}],"explanation":"The context window is measured in tokens; anything beyond it falls outside what the model can see at that moment."}]'::jsonb,
  null,
  array['artificial intelligence', 'generative ai', 'llm', 'machine learning']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-ia-generativa',
  'Trivia de inteligencia artificial generativa',
  'Ocho preguntas sobre IA generativa: tokens, transformers, entrenamiento, alucinaciones y los límites de estos sistemas.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"¿Qué produce un sistema de IA generativa?","options":[{"id":"a","text":"Contenido nuevo como texto, imágenes o audio","is_correct":true},{"id":"b","text":"Solo clasificaciones de datos existentes","is_correct":false},{"id":"c","text":"Objetos físicos bajo demanda","is_correct":false},{"id":"d","text":"Demostraciones matemáticas verificadas","is_correct":false}],"explanation":"Los modelos generativos crean contenido nuevo parecido a sus datos de entrenamiento, a diferencia de los sistemas que solo clasifican o predicen."},{"id":"q2","question":"En un modelo de lenguaje, ¿qué es un token?","options":[{"id":"a","text":"Un fragmento pequeño de texto, como una palabra o parte de ella","is_correct":true},{"id":"b","text":"Un nivel de suscripción de pago","is_correct":false},{"id":"c","text":"Una unidad de potencia de cómputo","is_correct":false},{"id":"d","text":"Una conversación guardada","is_correct":false}],"explanation":"Los modelos dividen el texto en tokens — palabras enteras, fragmentos o caracteres — y procesan esas piezas."},{"id":"q3","question":"¿Qué arquitectura, presentada en un artículo de 2017, sustenta los modelos de lenguaje actuales?","options":[{"id":"a","text":"El transformer","is_correct":true},{"id":"b","text":"El perceptrón","is_correct":false},{"id":"c","text":"El árbol de decisión","is_correct":false},{"id":"d","text":"La red convolucional","is_correct":false}],"explanation":"El artículo ''Attention Is All You Need'' introdujo el transformer, cuyo mecanismo de atención es la base de los LLM actuales."},{"id":"q4","question":"Durante el preentrenamiento, ¿qué aprende a hacer un modelo de lenguaje?","options":[{"id":"a","text":"Predecir el siguiente token de un texto","is_correct":true},{"id":"b","text":"Buscar respuestas en una base de datos","is_correct":false},{"id":"c","text":"Seguir un guion fijo","is_correct":false},{"id":"d","text":"Copiar páginas web palabra por palabra","is_correct":false}],"explanation":"El preentrenamiento ajusta miles de millones de pesos para que el modelo mejore prediciendo qué token sigue."},{"id":"q5","question":"¿Qué es una ''alucinación'' de la IA?","options":[{"id":"a","text":"Una respuesta segura de sí misma que en realidad es falsa o inventada","is_correct":true},{"id":"b","text":"Un modelo que se niega a responder","is_correct":false},{"id":"c","text":"Un error visual en la interfaz","is_correct":false},{"id":"d","text":"Un tipo de ciberataque","is_correct":false}],"explanation":"Las alucinaciones ocurren porque los modelos generan texto plausible sin una comprobación de verdad incorporada."},{"id":"q6","question":"¿Qué es el fine-tuning?","options":[{"id":"a","text":"Entrenamiento adicional de un modelo base con datos o tareas específicas","is_correct":true},{"id":"b","text":"Borrar la mitad del modelo para acelerarlo","is_correct":false},{"id":"c","text":"Reescribir el código fuente del modelo","is_correct":false},{"id":"d","text":"Conectar el modelo a internet","is_correct":false}],"explanation":"El fine-tuning toma un modelo preentrenado y sigue entrenándolo con datos más acotados para especializar su comportamiento."},{"id":"q7","question":"¿Qué aporta el RLHF al entrenamiento de un modelo?","options":[{"id":"a","text":"Retroalimentación humana que guía las respuestas hacia un comportamiento útil","is_correct":true},{"id":"b","text":"Más tarjetas gráficas en el centro de datos","is_correct":false},{"id":"c","text":"Un segundo modelo que traduce cada respuesta","is_correct":false},{"id":"d","text":"Reglas gramaticales fijas","is_correct":false}],"explanation":"El aprendizaje por refuerzo con retroalimentación humana usa las valoraciones de las personas para afinar el comportamiento del modelo."},{"id":"q8","question":"¿Qué es la ventana de contexto de un modelo?","options":[{"id":"a","text":"La cantidad máxima de texto que puede considerar a la vez","is_correct":true},{"id":"b","text":"El límite de tiempo para cada respuesta","is_correct":false},{"id":"c","text":"La pantalla donde aparecen los resultados","is_correct":false},{"id":"d","text":"El número de idiomas que conoce","is_correct":false}],"explanation":"La ventana de contexto se mide en tokens; lo que queda fuera de ella no es visible para el modelo en ese momento."}]'::jsonb,
  null,
  array['inteligencia artificial', 'ia generativa', 'modelos de lenguaje', 'tecnología']::text[],
  3,
  'published',
  false,
  false,
  now()
)
