insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-artemis-program-trivia',
  'Artemis Program Trivia: NASA''s Return to the Moon',
  'Eight questions on the Artemis program: the SLS rocket, the Orion capsule, the first missions and how it differs from Apollo.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is the main goal of NASA''s Artemis program?","options":[{"id":"a","text":"To return humans to the Moon and build a lasting presence","is_correct":true},{"id":"b","text":"To land humans on Mars this decade","is_correct":false},{"id":"c","text":"To build a hotel on the ISS","is_correct":false},{"id":"d","text":"To mine asteroids for gold","is_correct":false}],"explanation":"Artemis aims to take astronauts back to the Moon and establish a sustainable presence that also serves as a step toward Mars."},{"id":"q2","question":"Which rocket launches the Orion capsule on Artemis missions?","options":[{"id":"a","text":"The Space Launch System","is_correct":true},{"id":"b","text":"The Saturn V","is_correct":false},{"id":"c","text":"The Falcon 9","is_correct":false},{"id":"d","text":"The space shuttle","is_correct":false}],"explanation":"The SLS is NASA''s heavy-lift rocket for deep space; the Saturn V powered Apollo and the shuttle was retired in 2011."},{"id":"q3","question":"What was the Artemis I mission?","options":[{"id":"a","text":"An uncrewed test flight of Orion around the Moon","is_correct":true},{"id":"b","text":"The first crewed landing on the south pole","is_correct":false},{"id":"c","text":"A supply mission to the ISS","is_correct":false},{"id":"d","text":"A robotic rover mission","is_correct":false}],"explanation":"Artemis I flew without a crew in November and December 2022, testing Orion and the SLS in lunar orbit."},{"id":"q4","question":"Which agency provides Orion''s service module, which supplies power and propulsion?","options":[{"id":"a","text":"The European Space Agency","is_correct":true},{"id":"b","text":"The Japan Aerospace Exploration Agency","is_correct":false},{"id":"c","text":"Roscosmos","is_correct":false},{"id":"d","text":"The Indian Space Research Organisation","is_correct":false}],"explanation":"The European Service Module, built by ESA, carries Orion''s engines, solar arrays and life-support systems."},{"id":"q5","question":"What is the plan for the Artemis II mission?","options":[{"id":"a","text":"A crewed flight around the Moon without landing","is_correct":true},{"id":"b","text":"The first crewed landing on the surface","is_correct":false},{"id":"c","text":"An uncrewed cargo delivery","is_correct":false},{"id":"d","text":"A permanent base on the far side","is_correct":false}],"explanation":"Artemis II will carry four astronauts on a lunar flyby, testing Orion''s systems with a crew before the landing mission."},{"id":"q6","question":"Why is the lunar south pole the focus of the Artemis landings?","options":[{"id":"a","text":"Its permanently shadowed craters may hold water ice","is_correct":true},{"id":"b","text":"It has the warmest temperatures on the Moon","is_correct":false},{"id":"c","text":"Its flat terrain makes landing easy","is_correct":false},{"id":"d","text":"Apollo already covered the equator","is_correct":false}],"explanation":"Ice in shadowed craters could provide water, oxygen and even rocket propellant for future missions."},{"id":"q7","question":"What is the Gateway in the Artemis architecture?","options":[{"id":"a","text":"A small station planned to orbit the Moon","is_correct":true},{"id":"b","text":"The launch pad at Cape Canaveral","is_correct":false},{"id":"c","text":"Orion''s parachute system","is_correct":false},{"id":"d","text":"A network of lunar GPS satellites","is_correct":false}],"explanation":"Gateway is a planned lunar-orbit outpost where crews can dock and transfer to landers bound for the surface."},{"id":"q8","question":"Where does the name Artemis come from?","options":[{"id":"a","text":"The Greek goddess of the Moon and Apollo''s twin sister","is_correct":true},{"id":"b","text":"The first NASA administrator","is_correct":false},{"id":"c","text":"An acronym for a lunar research program","is_correct":false},{"id":"d","text":"The crater where Apollo 11 landed","is_correct":false}],"explanation":"In Greek mythology Artemis is Apollo''s twin sister and goddess of the Moon, a nod to the Apollo program."}]'::jsonb,
  null,
  array['artemis', 'nasa', 'moon', 'orion', 'space']::text[],
  3,
  'published',
  false,
  false,
  now()
)
