insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-programa-artemis',
  'Trivia del programa Artemis: el regreso a la Luna',
  'Ocho preguntas sobre el programa Artemis: el cohete SLS, la cápsula Orión, las primeras misiones y su diferencia con Apolo.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuál es el objetivo principal del programa Artemis de la NASA?","options":[{"id":"a","text":"Devolver astronautas a la Luna y construir una presencia duradera","is_correct":true},{"id":"b","text":"Llevar humanos a Marte en esta década","is_correct":false},{"id":"c","text":"Construir un hotel en la EEI","is_correct":false},{"id":"d","text":"Extraer oro de asteroides","is_correct":false}],"explanation":"Artemis busca llevar astronautas de vuelta a la Luna y crear una presencia sostenible que también sirva de paso hacia Marte."},{"id":"q2","question":"¿Qué cohete lanza la cápsula Orión en las misiones Artemis?","options":[{"id":"a","text":"El Space Launch System","is_correct":true},{"id":"b","text":"El Saturno V","is_correct":false},{"id":"c","text":"El Falcon 9","is_correct":false},{"id":"d","text":"El transbordador espacial","is_correct":false}],"explanation":"El SLS es el cohete de carga pesada de la NASA para el espacio profundo; el Saturno V impulsó el programa Apolo y el transbordador se retiró en 2011."},{"id":"q3","question":"¿Qué fue la misión Artemis I?","options":[{"id":"a","text":"Un vuelo de prueba de Orión alrededor de la Luna, sin tripulación","is_correct":true},{"id":"b","text":"El primer alunizaje tripulado en el polo sur","is_correct":false},{"id":"c","text":"Una misión de suministros a la EEI","is_correct":false},{"id":"d","text":"Una misión robótica con rover","is_correct":false}],"explanation":"Artemis I voló sin tripulación en noviembre y diciembre de 2022, probando Orión y el SLS en órbita lunar."},{"id":"q4","question":"¿Qué agencia aporta el módulo de servicio de Orión, que suministra energía y propulsión?","options":[{"id":"a","text":"La Agencia Espacial Europea","is_correct":true},{"id":"b","text":"La agencia espacial japonesa","is_correct":false},{"id":"c","text":"Roscosmos","is_correct":false},{"id":"d","text":"La agencia espacial india","is_correct":false}],"explanation":"El Módulo de Servicio Europeo, construido por la ESA, lleva los motores, paneles solares y sistemas de soporte vital de Orión."},{"id":"q5","question":"¿Qué tiene planeado la misión Artemis II?","options":[{"id":"a","text":"Un vuelo tripulado alrededor de la Luna sin alunizar","is_correct":true},{"id":"b","text":"El primer alunizaje tripulado en la superficie","is_correct":false},{"id":"c","text":"Una entrega de carga sin tripulación","is_correct":false},{"id":"d","text":"Una base permanente en la cara oculta","is_correct":false}],"explanation":"Artemis II llevará cuatro astronautas en un sobrevuelo lunar para probar los sistemas de Orión con tripulación antes del alunizaje."},{"id":"q6","question":"¿Por qué el polo sur lunar es el objetivo de los alunizajes Artemis?","options":[{"id":"a","text":"Sus cráteres en sombra permanente podrían contener hielo de agua","is_correct":true},{"id":"b","text":"Tiene las temperaturas más cálidas de la Luna","is_correct":false},{"id":"c","text":"Su terreno plano facilita el alunizaje","is_correct":false},{"id":"d","text":"Apolo ya cubrió la zona ecuatorial","is_correct":false}],"explanation":"El hielo de los cráteres en sombra podría aportar agua, oxígeno e incluso propelente para futuras misiones."},{"id":"q7","question":"¿Qué es el Gateway en la arquitectura Artemis?","options":[{"id":"a","text":"Una estación pequeña prevista para orbitar la Luna","is_correct":true},{"id":"b","text":"La plataforma de lanzamiento en Cabo Cañaveral","is_correct":false},{"id":"c","text":"El sistema de paracaídas de Orión","is_correct":false},{"id":"d","text":"Una red de satélites GPS lunares","is_correct":false}],"explanation":"Gateway es un puesto de avanzada en órbita lunar donde las tripulaciones podrán acoplar y transferirse a los módulos de descenso."},{"id":"q8","question":"¿De dónde viene el nombre Artemis?","options":[{"id":"a","text":"De la diosa griega de la Luna, hermana gemela de Apolo","is_correct":true},{"id":"b","text":"Del primer administrador de la NASA","is_correct":false},{"id":"c","text":"De un acrónimo de un programa de investigación lunar","is_correct":false},{"id":"d","text":"Del cráter donde alunizó el Apolo 11","is_correct":false}],"explanation":"En la mitología griega Artemisa es la hermana gemela de Apolo y diosa de la Luna, un guiño al programa Apolo."}]'::jsonb,
  null,
  array['artemis', 'nasa', 'luna', 'orion', 'espacio']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-space-telescopes-trivia',
  'Space Telescopes Trivia: From Hubble to James Webb',
  'Eight questions on space telescopes: why they orbit, what Hubble and James Webb observe and the observatories that changed astronomy.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Why do astronomers put telescopes in space?","options":[{"id":"a","text":"Earth''s atmosphere blurs images and absorbs many wavelengths","is_correct":true},{"id":"b","text":"Launching telescopes is cheaper than building them on the ground","is_correct":false},{"id":"c","text":"There is no gravity to distort the mirrors","is_correct":false},{"id":"d","text":"Governments ban large telescopes on land","is_correct":false}],"explanation":"Atmospheric turbulence blurs starlight and the air blocks infrared, ultraviolet and X-rays, so space gives a clearer view."},{"id":"q2","question":"Which part of the spectrum does the James Webb Space Telescope mainly observe?","options":[{"id":"a","text":"Infrared","is_correct":true},{"id":"b","text":"Visible light","is_correct":false},{"id":"c","text":"X-rays","is_correct":false},{"id":"d","text":"Radio waves","is_correct":false}],"explanation":"Webb works in infrared, which lets it see through dust clouds and detect light from the earliest, most distant galaxies."},{"id":"q3","question":"What is Webb''s primary mirror made of?","options":[{"id":"a","text":"18 gold-coated beryllium segments, 6.5 metres across","is_correct":true},{"id":"b","text":"A single glass mirror like Hubble''s","is_correct":false},{"id":"c","text":"A liquid mercury dish","is_correct":false},{"id":"d","text":"A cluster of radio antennas","is_correct":false}],"explanation":"The 18 hexagonal segments fold for launch and unfold in space; gold reflects infrared light efficiently."},{"id":"q4","question":"Where does the James Webb telescope orbit?","options":[{"id":"a","text":"At the Sun-Earth L2 point, about 1.5 million km from Earth","is_correct":true},{"id":"b","text":"In low Earth orbit next to the ISS","is_correct":false},{"id":"c","text":"In orbit around the Moon","is_correct":false},{"id":"d","text":"In orbit around Mars","is_correct":false}],"explanation":"From L2, Webb''s sunshield can block the Sun, Earth and Moon at once, keeping the instruments cold."},{"id":"q5","question":"In what year was the Hubble Space Telescope launched?","options":[{"id":"a","text":"1990","is_correct":true},{"id":"b","text":"1969","is_correct":false},{"id":"c","text":"1981","is_correct":false},{"id":"d","text":"2001","is_correct":false}],"explanation":"The space shuttle Discovery deployed Hubble in April 1990; astronauts corrected its flawed mirror in 1993."},{"id":"q6","question":"Which space observatory studies the universe in X-rays?","options":[{"id":"a","text":"The Chandra X-ray Observatory","is_correct":true},{"id":"b","text":"The Kepler telescope","is_correct":false},{"id":"c","text":"The Hubble telescope","is_correct":false},{"id":"d","text":"The Gaia spacecraft","is_correct":false}],"explanation":"Chandra, launched in 1999, detects X-rays from black holes, supernova remnants and hot galaxy clusters."},{"id":"q7","question":"What was the Kepler space telescope built to find?","options":[{"id":"a","text":"Exoplanets, by detecting tiny dips in starlight","is_correct":true},{"id":"b","text":"Asteroids approaching Earth","is_correct":false},{"id":"c","text":"Dark matter particles","is_correct":false},{"id":"d","text":"Gravitational waves","is_correct":false}],"explanation":"Kepler watched more than 150,000 stars for the dimming caused by transiting planets and found thousands."},{"id":"q8","question":"What is the Gaia mission''s main achievement?","options":[{"id":"a","text":"Mapping the positions and motions of more than a billion stars","is_correct":true},{"id":"b","text":"Photographing the surface of Pluto","is_correct":false},{"id":"c","text":"Landing a probe on a comet","is_correct":false},{"id":"d","text":"Detecting the first exoplanet","is_correct":false}],"explanation":"ESA''s Gaia measured more than a billion stars, producing the most precise 3D map of the Milky Way so far."}]'::jsonb,
  null,
  array['telescopes', 'hubble', 'james webb', 'astronomy', 'space']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-telescopios-espaciales',
  'Trivia de telescopios espaciales: de Hubble a Webb',
  'Ocho preguntas sobre telescopios espaciales: por qué orbitan, qué observan Hubble y James Webb y los observatorios que cambiaron la astronomía.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Por qué los astrónomos ponen telescopios en el espacio?","options":[{"id":"a","text":"La atmósfera terrestre difumina las imágenes y absorbe muchas longitudes de onda","is_correct":true},{"id":"b","text":"Lanzar telescopios es más barato que construirlos en tierra","is_correct":false},{"id":"c","text":"No hay gravedad que deforme los espejos","is_correct":false},{"id":"d","text":"Los gobiernos prohíben telescopios grandes en tierra","is_correct":false}],"explanation":"La turbulencia atmosférica difumina la luz de las estrellas y el aire bloquea el infrarrojo, el ultravioleta y los rayos X, así que el espacio ofrece una visión más limpia."},{"id":"q2","question":"¿Qué parte del espectro observa principalmente el telescopio espacial James Webb?","options":[{"id":"a","text":"El infrarrojo","is_correct":true},{"id":"b","text":"La luz visible","is_correct":false},{"id":"c","text":"Los rayos X","is_correct":false},{"id":"d","text":"Las ondas de radio","is_correct":false}],"explanation":"Webb trabaja en infrarrojo, lo que le permite ver a través de las nubes de polvo y detectar la luz de las galaxias más antiguas y lejanas."},{"id":"q3","question":"¿Cómo es el espejo principal de Webb?","options":[{"id":"a","text":"18 segmentos de berilio bañados en oro, de 6,5 metros en total","is_correct":true},{"id":"b","text":"Un espejo de vidrio único como el de Hubble","is_correct":false},{"id":"c","text":"Un plato de mercurio líquido","is_correct":false},{"id":"d","text":"Un conjunto de antenas de radio","is_correct":false}],"explanation":"Los 18 segmentos hexagonales se pliegan para el lanzamiento y se despliegan en el espacio; el oro refleja bien la luz infrarroja."},{"id":"q4","question":"¿Dónde orbita el telescopio James Webb?","options":[{"id":"a","text":"En el punto L2 Sol-Tierra, a unos 1,5 millones de km de la Tierra","is_correct":true},{"id":"b","text":"En órbita baja, junto a la EEI","is_correct":false},{"id":"c","text":"En órbita alrededor de la Luna","is_correct":false},{"id":"d","text":"En órbita alrededor de Marte","is_correct":false}],"explanation":"Desde L2, el parasol de Webb puede bloquear a la vez el Sol, la Tierra y la Luna, manteniendo fríos los instrumentos."},{"id":"q5","question":"¿En qué año se lanzó el telescopio espacial Hubble?","options":[{"id":"a","text":"1990","is_correct":true},{"id":"b","text":"1969","is_correct":false},{"id":"c","text":"1981","is_correct":false},{"id":"d","text":"2001","is_correct":false}],"explanation":"El transbordador Discovery desplegó el Hubble en abril de 1990; en 1993 los astronautas corrigieron su espejo defectuoso."},{"id":"q6","question":"¿Qué observatorio espacial estudia el universo en rayos X?","options":[{"id":"a","text":"El Observatorio de rayos X Chandra","is_correct":true},{"id":"b","text":"El telescopio Kepler","is_correct":false},{"id":"c","text":"El telescopio Hubble","is_correct":false},{"id":"d","text":"La sonda Gaia","is_correct":false}],"explanation":"Chandra, lanzado en 1999, detecta rayos X de agujeros negros, restos de supernova y cúmulos de galaxias calientes."},{"id":"q7","question":"¿Para qué se construyó el telescopio espacial Kepler?","options":[{"id":"a","text":"Para encontrar exoplanetas detectando pequeñas caídas en el brillo de las estrellas","is_correct":true},{"id":"b","text":"Para vigilar asteroides que se acercan a la Tierra","is_correct":false},{"id":"c","text":"Para detectar partículas de materia oscura","is_correct":false},{"id":"d","text":"Para medir ondas gravitacionales","is_correct":false}],"explanation":"Kepler observó más de 150.000 estrellas en busca de los oscurecimientos que causan los planetas en tránsito y encontró miles."},{"id":"q8","question":"¿Cuál es el principal logro de la misión Gaia?","options":[{"id":"a","text":"Mapear la posición y el movimiento de más de mil millones de estrellas","is_correct":true},{"id":"b","text":"Fotografiar la superficie de Plutón","is_correct":false},{"id":"c","text":"Posar una sonda sobre un cometa","is_correct":false},{"id":"d","text":"Detectar el primer exoplaneta","is_correct":false}],"explanation":"Gaia, de la ESA, midió más de mil millones de estrellas y creó el mapa 3D más preciso de la Vía Láctea hasta ahora."}]'::jsonb,
  null,
  array['telescopios', 'hubble', 'james webb', 'astronomía', 'espacio']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-mars-missions-trivia',
  'Mars Missions Trivia: Rovers, Orbiters and Landers',
  'Eight questions on Mars exploration: the first landers, the rovers, the Ingenuity helicopter and what they discovered.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Which spacecraft made the first fully successful landing on Mars in 1976?","options":[{"id":"a","text":"Viking 1","is_correct":true},{"id":"b","text":"Mars 3","is_correct":false},{"id":"c","text":"Mariner 9","is_correct":false},{"id":"d","text":"Pathfinder","is_correct":false}],"explanation":"Viking 1 operated on the surface for years; the Soviet Mars 3 landed in 1971 but failed seconds later."},{"id":"q2","question":"What was Sojourner, which reached Mars in 1997 with the Pathfinder lander?","options":[{"id":"a","text":"The first rover to drive on Mars","is_correct":true},{"id":"b","text":"The first orbiter of the planet","is_correct":false},{"id":"c","text":"A stationary weather station","is_correct":false},{"id":"d","text":"A sample-return capsule","is_correct":false}],"explanation":"The microwave-sized Sojourner proved that mobile robots could explore the Martian surface."},{"id":"q3","question":"How did the Curiosity rover reach the Martian surface in 2012?","options":[{"id":"a","text":"Lowered on cables by a rocket-powered sky crane","is_correct":true},{"id":"b","text":"Bouncing inside giant airbags","is_correct":false},{"id":"c","text":"Gliding on a parachute until touchdown","is_correct":false},{"id":"d","text":"Inside a foam crash capsule","is_correct":false}],"explanation":"The sky crane lowered Curiosity on tethers and then flew away, a landing method Perseverance reused."},{"id":"q4","question":"What is the Perseverance rover''s main task in Jezero crater?","options":[{"id":"a","text":"Collecting and caching rock samples for a future return to Earth","is_correct":true},{"id":"b","text":"Digging for liquid water","is_correct":false},{"id":"c","text":"Building a habitat for astronauts","is_correct":false},{"id":"d","text":"Planting the first seeds on Mars","is_correct":false}],"explanation":"Perseverance seals rock cores in tubes for a planned mission to pick them up and bring them to Earth."},{"id":"q5","question":"What did the Ingenuity helicopter prove in April 2021?","options":[{"id":"a","text":"That powered flight is possible in Mars''s thin atmosphere","is_correct":true},{"id":"b","text":"That drones can return samples to orbit","is_correct":false},{"id":"c","text":"That Mars has enough oxygen to fly","is_correct":false},{"id":"d","text":"That helicopters need no maintenance","is_correct":false}],"explanation":"Ingenuity made the first powered, controlled flight on another planet and flew 72 times before retiring in 2024."},{"id":"q6","question":"Which rover explored Mars for nearly 15 years until a dust storm ended its mission in 2018?","options":[{"id":"a","text":"Opportunity","is_correct":true},{"id":"b","text":"Spirit","is_correct":false},{"id":"c","text":"Curiosity","is_correct":false},{"id":"d","text":"Zhurong","is_correct":false}],"explanation":"Opportunity was designed for 90 days but drove more than 45 km; a global dust storm blocked its solar panels in 2018."},{"id":"q7","question":"Which country landed the Zhurong rover on Mars in 2021 with the Tianwen-1 mission?","options":[{"id":"a","text":"China","is_correct":true},{"id":"b","text":"India","is_correct":false},{"id":"c","text":"Japan","is_correct":false},{"id":"d","text":"The United Arab Emirates","is_correct":false}],"explanation":"Zhurong made China the second country to operate a rover on Mars; the UAE''s Hope probe, launched in the same window, is an orbiter."},{"id":"q8","question":"What did the InSight lander measure on Mars between 2018 and 2022?","options":[{"id":"a","text":"Marsquakes and the planet''s interior structure","is_correct":true},{"id":"b","text":"The composition of Mars''s ice caps","is_correct":false},{"id":"c","text":"Radiation levels for future crews","is_correct":false},{"id":"d","text":"The chemistry of the atmosphere","is_correct":false}],"explanation":"InSight''s seismometer recorded more than 1,300 marsquakes, revealing the size of the planet''s core."}]'::jsonb,
  null,
  array['mars', 'nasa', 'rovers', 'perseverance', 'space']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-misiones-a-marte',
  'Trivia de misiones a Marte: rovers y orbitadores',
  'Ocho preguntas sobre la exploración de Marte: los primeros aterrizajes, los rovers, el helicóptero Ingenuity y sus descubrimientos.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Qué nave logró el primer aterrizaje suave totalmente exitoso en Marte en 1976?","options":[{"id":"a","text":"Viking 1","is_correct":true},{"id":"b","text":"Mars 3","is_correct":false},{"id":"c","text":"Mariner 9","is_correct":false},{"id":"d","text":"Pathfinder","is_correct":false}],"explanation":"Viking 1 operó en la superficie durante años; la soviética Mars 3 aterrizó en 1971 pero falló segundos después."},{"id":"q2","question":"¿Qué fue Sojourner, que llegó a Marte en 1997 con el módulo Pathfinder?","options":[{"id":"a","text":"El primer rover que se desplazó por Marte","is_correct":true},{"id":"b","text":"El primer orbitador del planeta","is_correct":false},{"id":"c","text":"Una estación meteorológica fija","is_correct":false},{"id":"d","text":"Una cápsula de retorno de muestras","is_correct":false}],"explanation":"La pequeña Sojourner demostró que los robots móviles podían explorar la superficie marciana."},{"id":"q3","question":"¿Cómo llegó el rover Curiosity a la superficie de Marte en 2012?","options":[{"id":"a","text":"Descendió colgado de cables desde una grúa propulsada por cohetes","is_correct":true},{"id":"b","text":"Rebotando dentro de airbags gigantes","is_correct":false},{"id":"c","text":"Planeando con paracaídas hasta el suelo","is_correct":false},{"id":"d","text":"Dentro de una cápsula de espuma","is_correct":false}],"explanation":"La grúa aérea bajó a Curiosity con cables y luego se alejó volando, un método que repitió Perseverance."},{"id":"q4","question":"¿Cuál es la tarea principal del rover Perseverance en el cráter Jezero?","options":[{"id":"a","text":"Recoger y guardar muestras de roca para un futuro retorno a la Tierra","is_correct":true},{"id":"b","text":"Excavar en busca de agua líquida","is_correct":false},{"id":"c","text":"Construir un hábitat para astronautas","is_correct":false},{"id":"d","text":"Plantar las primeras semillas en Marte","is_correct":false}],"explanation":"Perseverance sella testigos de roca en tubos para que una misión prevista los recoja y los traiga a la Tierra."},{"id":"q5","question":"¿Qué demostró el helicóptero Ingenuity en abril de 2021?","options":[{"id":"a","text":"Que el vuelo propulsado es posible en la tenue atmósfera de Marte","is_correct":true},{"id":"b","text":"Que los drones pueden devolver muestras a órbita","is_correct":false},{"id":"c","text":"Que Marte tiene oxígeno suficiente para volar","is_correct":false},{"id":"d","text":"Que los helicópteros no necesitan mantenimiento","is_correct":false}],"explanation":"Ingenuity hizo el primer vuelo propulsado y controlado en otro planeta y voló 72 veces antes de retirarse en 2024."},{"id":"q6","question":"¿Qué rover exploró Marte casi 15 años hasta que una tormenta de polvo terminó su misión en 2018?","options":[{"id":"a","text":"Opportunity","is_correct":true},{"id":"b","text":"Spirit","is_correct":false},{"id":"c","text":"Curiosity","is_correct":false},{"id":"d","text":"Zhurong","is_correct":false}],"explanation":"Opportunity fue diseñado para 90 días pero recorrió más de 45 km; una tormenta global de polvo bloqueó sus paneles solares en 2018."},{"id":"q7","question":"¿Qué país aterrizó el rover Zhurong en Marte en 2021 con la misión Tianwen-1?","options":[{"id":"a","text":"China","is_correct":true},{"id":"b","text":"India","is_correct":false},{"id":"c","text":"Japón","is_correct":false},{"id":"d","text":"Emiratos Árabes Unidos","is_correct":false}],"explanation":"Zhurong convirtió a China en el segundo país en operar un rover en Marte; la sonda Hope de EAU, lanzada en la misma ventana, es un orbitador."},{"id":"q8","question":"¿Qué midió el módulo InSight en Marte entre 2018 y 2022?","options":[{"id":"a","text":"Los martemotos y la estructura interna del planeta","is_correct":true},{"id":"b","text":"La composición de los casquetes polares de Marte","is_correct":false},{"id":"c","text":"Los niveles de radiación para futuras tripulaciones","is_correct":false},{"id":"d","text":"La química de la atmósfera","is_correct":false}],"explanation":"El sismómetro de InSight registró más de 1.300 martemotos y reveló el tamaño del núcleo del planeta."}]'::jsonb,
  null,
  array['marte', 'nasa', 'rovers', 'perseverance', 'espacio']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

